-- Initial BuildMart ERP schema. Generated-equivalent baseline for PostgreSQL.
CREATE TYPE "Role" AS ENUM ('ADMIN','MANAGER','STAFF');
CREATE TYPE "InvoiceKind" AS ENUM ('SALE','PURCHASE');
CREATE TYPE "InvoiceStatus" AS ENUM ('DRAFT','POSTED','CANCELLED');
CREATE TYPE "PaymentMode" AS ENUM ('CASH','CARD','UPI','BANK_TRANSFER','CHEQUE','CREDIT');
CREATE TYPE "MovementType" AS ENUM ('OPENING','PURCHASE','SALE','ADJUSTMENT','RETURN');
CREATE TYPE "TaxType" AS ENUM ('INTRA_STATE','INTER_STATE');
CREATE TABLE "Company" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"gstin" TEXT,"pan" TEXT,"address" TEXT,"city" TEXT,"state" TEXT,"stateCode" TEXT,"pincode" TEXT,"phone" TEXT,"email" TEXT,"invoicePrefix" TEXT NOT NULL DEFAULT 'INV',"financialYear" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'STAFF',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE);
CREATE TABLE "Item" ("id" TEXT PRIMARY KEY,"sku" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"categoryId" TEXT,"unit" TEXT NOT NULL DEFAULT 'Nos',"hsnCode" TEXT,"gstRate" DECIMAL(5,2) NOT NULL DEFAULT 18,"purchaseRate" DECIMAL(12,2) NOT NULL DEFAULT 0,"sellingRate" DECIMAL(12,2) NOT NULL DEFAULT 0,"reorderLevel" DECIMAL(12,3) NOT NULL DEFAULT 0,"currentStock" DECIMAL(12,3) NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Item_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"phone" TEXT,"email" TEXT,"gstin" TEXT,"address" TEXT,"city" TEXT,"state" TEXT,"stateCode" TEXT,"pincode" TEXT,"creditLimit" DECIMAL(12,2) NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Supplier" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"phone" TEXT,"email" TEXT,"gstin" TEXT,"address" TEXT,"city" TEXT,"state" TEXT,"stateCode" TEXT,"pincode" TEXT,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Invoice" ("id" TEXT PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"kind" "InvoiceKind" NOT NULL,"status" "InvoiceStatus" NOT NULL DEFAULT 'DRAFT',"issueDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"dueDate" TIMESTAMP(3),"customerId" TEXT,"supplierId" TEXT,"taxType" "TaxType" NOT NULL DEFAULT 'INTRA_STATE',"subtotal" DECIMAL(14,2) NOT NULL DEFAULT 0,"discount" DECIMAL(14,2) NOT NULL DEFAULT 0,"cgst" DECIMAL(14,2) NOT NULL DEFAULT 0,"sgst" DECIMAL(14,2) NOT NULL DEFAULT 0,"igst" DECIMAL(14,2) NOT NULL DEFAULT 0,"freight" DECIMAL(14,2) NOT NULL DEFAULT 0,"roundOff" DECIMAL(14,2) NOT NULL DEFAULT 0,"total" DECIMAL(14,2) NOT NULL DEFAULT 0,"notes" TEXT,"eInvoiceIrn" TEXT,"eInvoiceAckNo" TEXT,"eInvoiceAckDate" TIMESTAMP(3),"eWayBillNo" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Invoice_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "Invoice_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "Invoice_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "InvoiceLine" ("id" TEXT PRIMARY KEY,"invoiceId" TEXT NOT NULL,"itemId" TEXT NOT NULL,"description" TEXT,"quantity" DECIMAL(12,3) NOT NULL,"rate" DECIMAL(12,2) NOT NULL,"discount" DECIMAL(12,2) NOT NULL DEFAULT 0,"gstRate" DECIMAL(5,2) NOT NULL,"taxableAmount" DECIMAL(14,2) NOT NULL,"taxAmount" DECIMAL(14,2) NOT NULL,"lineTotal" DECIMAL(14,2) NOT NULL,CONSTRAINT "InvoiceLine_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "Invoice"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "InvoiceLine_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY,"invoiceId" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"mode" "PaymentMode" NOT NULL,"reference" TEXT,"paidAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"receivedById" TEXT NOT NULL,CONSTRAINT "Payment_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "Invoice"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "Payment_receivedById_fkey" FOREIGN KEY ("receivedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "StockMovement" ("id" TEXT PRIMARY KEY,"itemId" TEXT NOT NULL,"invoiceId" TEXT,"type" "MovementType" NOT NULL,"quantity" DECIMAL(12,3) NOT NULL,"balanceAfter" DECIMAL(12,3) NOT NULL,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StockMovement_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "StockMovement_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "Invoice"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "Invoice_kind_status_issueDate_idx" ON "Invoice"("kind","status","issueDate");
CREATE INDEX "StockMovement_itemId_createdAt_idx" ON "StockMovement"("itemId","createdAt");
